import assert from "node:assert/strict";
import { test } from "node:test";
import { deploy } from "../src/cli/deploy.js";

function capture() {
  const lines = [];
  return { lines, log: (line) => lines.push(line) };
}

test("dry run skips the steps and says so", async () => {
  const { lines, log } = capture();
  await deploy(["--dry-run"], log);
  assert.equal(lines.at(-1), "dry run: 3 steps skipped");
});

test("a full deploy reports every step", async () => {
  const { lines, log } = capture();
  await deploy([], log);
  assert.deepEqual(lines, ["-> build", "-> upload", "-> activate", "deployed: 3 steps"]);
});

function recordingTarget() {
  const calls = [];
  return {
    calls,
    build: () => calls.push("build"),
    upload: () => calls.push("upload"),
    activate: () => calls.push("activate"),
  };
}

test("runs each step against the target it is given, in order", async () => {
  const { log } = capture();
  const target = recordingTarget();
  await deploy([], log, target);
  assert.deepEqual(target.calls, ["build", "upload", "activate"]);
});

test("dry run never touches the target", async () => {
  const { log } = capture();
  const target = recordingTarget();
  await deploy(["--dry-run"], log, target);
  assert.deepEqual(target.calls, []);
});

test("async steps finish in order before the deploy reports success", async () => {
  const { lines, log } = capture();
  const events = [];
  const step = (name) => async () => {
    events.push(`start ${name}`);
    await new Promise((resolve) => setTimeout(resolve, 5));
    events.push(`end ${name}`);
  };
  await deploy([], log, { build: step("build"), upload: step("upload"), activate: step("activate") });
  assert.deepEqual(events, [
    "start build", "end build",
    "start upload", "end upload",
    "start activate", "end activate",
  ]);
  assert.equal(lines.at(-1), "deployed: 3 steps");
});

test("a failing step fails the deploy and stops the later steps", async () => {
  const { lines, log } = capture();
  const target = recordingTarget();
  target.upload = async () => {
    throw new Error("upload refused");
  };
  await assert.rejects(deploy([], log, target), /upload refused/);
  assert.deepEqual(target.calls, ["build"]);
  assert.ok(!lines.includes("deployed: 3 steps"));
});

test("a target missing a step is rejected before any step runs", async () => {
  const { lines, log } = capture();
  const target = recordingTarget();
  delete target.activate;
  await assert.rejects(deploy([], log, target), /target does not implement: activate/);
  assert.deepEqual(target.calls, []);
  assert.deepEqual(lines, []);
});
